#include <stdio.h>
#include <string.h>

#define MAX_PLUGINS 10

typedef struct { char name[32]; int version; void (*execute)(void); } Plugin;

Plugin *registry[MAX_PLUGINS];
int plugin_count = 0;

void register_plugin(Plugin *p) {
    if (plugin_count < MAX_PLUGINS) registry[plugin_count++] = p;
}

void run_plugin(char *name) {
    for (int i = 0; i < plugin_count; i++)
        if (strcmp(registry[i]->name, name) == 0) registry[i]->execute();
}

void math_plugin() { printf("Math: 5 + 3 = %d\n", 5+3); }
void print_plugin() { printf("Print: Hello from plugin!\n"); }

int main() {
    Plugin math = {"math", 1, math_plugin};
    Plugin print = {"print", 1, print_plugin};
    register_plugin(&math);
    register_plugin(&print);
    run_plugin("math");
    run_plugin("print");
    return 0;
}
